questionvariables.text:
/* Shared Question Bank Place Value, Rounding and Standard Form PVRS-04
Procedural task: round a positive whole number to a specified number of significant figures.
Interaction reference: Numbas NUMBAS-169559 "Significant figures: rounding"
This STACK implementation is independently authored. No source wording or generated mathematical content is copied. */
/* Use six-digit whole numbers so the first significant digit is unambiguous.
Target either 2 or 3 significant figures. */
sf_count: rand_with_prohib(2,3,[]);
/* Generate digits explicitly.
The first digit is non-zero. The later decision digit is forced to at least 5 so that truncation is always distinguishable from correct rounding. */
d1: rand_with_prohib(1,8,[]);
d2: rand_with_prohib(0,8,[]);
d3: if sf_count=2 then rand_with_prohib(5,9,[]) else rand_with_prohib(0,8,[]);
d4: if sf_count=3 then rand_with_prohib(5,9,[]) else rand_with_prohib(0,9,[]);
d5: rand_with_prohib(0,9,[]);
d6: rand_with_prohib(0,9,[]);
number: d1*100000 + d2*10000 + d3*1000 + d4*100 + d5*10 + d6;
/* For a six-digit number:
2 significant figures -> round to 10,000 3 significant figures -> round to 1,000 */
place_value: if sf_count=2 then 10000 else 1000;
/* Explicit school half-up rounding. */
answer: floor( ( number + place_value/2 ) / place_value ) * place_value;
/* Misconception 1: truncate instead of rounding. */
wrong_truncate: floor( number/place_value ) * place_value;
/* Misconception 2: treat significant figures like decimal places and leave the whole number unchanged. */
wrong_decimal_places: number;
/* Display values. */
number_display: number;
answer_display: answer;
